def count(a, start, remaining):
    if remaining == 0:
        return 1                       # a complete group (all numbers are positive)
    total = 0
    for i in range(start, len(a)):
        if a[i] > remaining:
            break                      # sorted: nothing later can fit
        if i > start and a[i] == a[i - 1]:
            continue                   # the same value was just tried here
        total += count(a, i + 1, remaining - a[i])
    return total

